import Foundation
import MongoKitten

/// A document of the "authors" collection. A property stays nil until it is set or read.
public struct Author: Sendable, Equatable {
    public var id: UUID?
    public var email: String?
    /// As it was read: a change writes only what differs
    var loadedDocument = Loaded()

    public init(id: UUID? = nil, email: String? = nil) {
        self.id = id
        self.email = email
    }
}

extension Author: DocumentValue {
    /// What a document holds.
    static func from(_ document: BsonDocument) throws -> Author {
        var entity = Author(
            id: try Bson.read(document, "_id", Bson.asUUID),
            email: try Bson.read(document, "email", Bson.asText))
        entity.loadedDocument = Loaded(document: try entity.toDocument())
        return entity
    }

    /// Its document: what is nil is left out.
    func toDocument() throws -> BsonDocument {
        var document: BsonDocument = [:]
        try Bson.write(&document, "_id", self.id, Bson.ofUUID)
        try Bson.write(&document, "email", self.email, Bson.ofText)
        return document
    }
}

import Foundation
import MongoKitten

/// A document of the "posts" collection. A property stays nil until it is set or read.
public struct Post: Sendable, Equatable {
    public var id: UUID?
    public var title: String?
    public var author: UUID?
    public var publishedAt: Date?
    public var comments: [Post.Comment]?
    /// As it was read: a change writes only what differs
    var loadedDocument = Loaded()

    public init(id: UUID? = nil, title: String? = nil, author: UUID? = nil, publishedAt: Date? = nil, comments: [Post.Comment]? = nil) {
        self.id = id
        self.title = title
        self.author = author
        self.publishedAt = publishedAt
        self.comments = comments
    }

    /// A nested document: it is stored with the one that holds it.
    public struct Comment: Sendable, Equatable {
        public var id: UUID?
        public var text: String?
        public var marks: [UUID]?

        public init(id: UUID? = nil, text: String? = nil, marks: [UUID]? = nil) {
            self.id = id
            self.text = text
            self.marks = marks
        }
    }
}

extension Post: DocumentValue {
    /// What a document holds.
    static func from(_ document: BsonDocument) throws -> Post {
        var entity = Post(
            id: try Bson.read(document, "_id", Bson.asUUID),
            title: try Bson.read(document, "title", Bson.asText),
            author: try Bson.read(document, "author", Bson.asUUID),
            publishedAt: try Bson.read(document, "published_at", Bson.asDate),
            comments: try Bson.read(document, "comments", Bson.asList(Bson.asNested(Post.Comment.self))))
        entity.loadedDocument = Loaded(document: try entity.toDocument())
        return entity
    }

    /// Its document: what is nil is left out.
    func toDocument() throws -> BsonDocument {
        var document: BsonDocument = [:]
        try Bson.write(&document, "_id", self.id, Bson.ofUUID)
        try Bson.write(&document, "title", self.title, Bson.ofText)
        try Bson.write(&document, "author", self.author, Bson.ofUUID)
        try Bson.write(&document, "published_at", self.publishedAt, Bson.ofDate)
        try Bson.write(&document, "comments", self.comments, Bson.ofList(Bson.ofNested))
        return document
    }
}

extension Post.Comment: DocumentValue {
    /// What a document holds.
    static func from(_ document: BsonDocument) throws -> Post.Comment {
        return Post.Comment(
            id: try Bson.read(document, "id", Bson.asUUID),
            text: try Bson.read(document, "text", Bson.asText),
            marks: try Bson.read(document, "marks", Bson.asList(Bson.asUUID)))
    }

    /// Its document: what is nil is left out.
    func toDocument() throws -> BsonDocument {
        var document: BsonDocument = [:]
        try Bson.write(&document, "id", self.id, Bson.ofUUID)
        try Bson.write(&document, "text", self.text, Bson.ofText)
        try Bson.write(&document, "marks", self.marks, Bson.ofList(Bson.ofUUID))
        return document
    }
}

