    @discardableResult
    public func addComment(_ id: UUID, _ comment: Post.Comment) async throws -> Post {
        var errors: [FieldError] = []
        checkPostComment(comment, "comments", &errors)
        if !errors.isEmpty { throw DomainError.validationFailed(entity: "Post", errors: errors) }
        return try await unitOfWork.transaction { uow in
            _ = try await find(uow, id)
            guard let changed = try await uow.posts.addComment(id, comment) else {
                throw DomainError.notFound(entity: "Post", key: "\(id)")
            }
            return changed
        }
    }

    /// Removes an item from comments, by its position.
    @discardableResult
    public func removeComment(_ id: UUID, _ position: Int) async throws -> Post {
