    var errors: [FieldError] = []
    if values.id ?? nil == nil && (creating || values.id != nil) {
        errors.append(FieldError("_id", "is required"))
    }
    if values.title ?? nil == nil && (creating || values.title != nil) {
        errors.append(FieldError("title", "is required"))
    }
    if values.author ?? nil == nil && (creating || values.author != nil) {
        errors.append(FieldError("author", "is required"))
    }
    if let value = values.comments ?? nil {
        for (i0, item0) in value.enumerated() {
