/// Rows for the tests: valid values for every column, and the rows they point to.
enum Factories {
    /// A valid Author that is not stored yet; n makes its unique values differ.
    static func newAuthor(_ n: Int) -> Author {
        Author(id: UUID(uuidString: String(format: "00000000-0000-4000-8000-%012d", n))!, email: "email-\(n)")
    }

    /// A stored Author.
    @discardableResult
    static func addAuthor(_ uow: any UnitOfWork, _ n: Int) async throws -> Author {
        let entity = newAuthor(n)
        return try await uow.authors.insert(entity)
    }

    /// A valid Post that is not stored yet; n makes its unique values differ.
    static func newPost(_ n: Int) -> Post {
        Post(id: UUID(uuidString: String(format: "00000000-0000-4000-8000-%012d", n))!, title: "title-\(n)", publishedAt: Date(timeIntervalSince1970: TimeInterval(1_767_268_800 + (n % 28) * 86_400)), comments: [newPostComment(n)])
    }

    /// A stored Post, with the rows it points to.
    @discardableResult
    static func addPost(_ uow: any UnitOfWork, _ n: Int) async throws -> Post {
        let parent0 = try await addAuthor(uow, n)
        var entity = newPost(n)
        entity.author = parent0.id
        return try await uow.posts.insert(entity)
    }

    /// A valid Post.Comment; n makes its values differ.
    static func newPostComment(_ n: Int) -> Post.Comment {
        Post.Comment(id: UUID(uuidString: String(format: "00000000-0000-4000-8000-%012d", n))!, text: "text-\(n)", marks: [])
    }
}

